 if Path(current)==root:
  dirs[:]=[name for name in dirs if name"'!='"'.git']
 for name in dirs+names:
  p=Path(current)/name
  rel=p.relative_to(root).as_posix()
  assert not p.is_symlink(),rel
  assert rel in files|parents|empty_dirs|managed,rel
 dirs[:]=[name for name in dirs if (Path(current)/name).relative_to(root).as_posix() not in managed]
