config=json.loads((root/'roadmap/roadmap.config.json').read_text())
assert config['gateCommands']==gates and set(config['gateCommands'])=={'lint','types','unit','integration','build','e2e','emit'}
assert all('capbuild' not in value for value in gates.values())
assert config['designHomes']=={'architecture':{'home':'docs/architecture.md'},'ux':{'canon':['docs/ux-canon.md']}}
assert '"'$schema'"' not in config
assert json.loads((root/'reviews/changelog.json').read_text())=={'versions':[]}
plugin=Path('/home/patrik/zeroh-marketplace-codex-29-30-31-32-33-34/plugins/zeroh-roadmap')
for name in ['schema.ts','registry.ts','emit.ts']:
 assert (root/'roadmap/lib'/name).read_bytes()==(plugin/'templates'/name).read_bytes(),name
for name in ['ROADMAP.md','backlog.ts']:
 assert (root/'roadmap'/name).read_bytes()==(plugin/'templates'/name).read_bytes(),name
for name in ['pre-review.sh','build-dashboard.sh','generate-changelog-md.ts']:
 assert (root/'scripts'/name).read_bytes()==(plugin/'scripts'/name).read_bytes(),name
assert hashlib.sha256((root/'scripts/check-readme-catalog.mjs').read_bytes()).hexdigest()=='7cdfebbbcae1b9638fcdb557676f8a3311526e28856fdc0b975ba3d30ad38bbb'
assert hashlib.sha256(Path('/home/patrik/.local/bin/capbuild').read_bytes()).hexdigest()=='f71688b5aa30a7bdc2a900c20593c625192bce54cc7713d66dfd40dca7fc2083'
assert (root/'CLAUDE.md').read_text().startswith('@AGENTS.md\\n')
